60	@RestController
61	@CrossOrigin(exposedHeaders = "errors, content-type")
62	@RequestMapping("/api")
63	public class OwnerRestControllerV1 implements OwnersApi {
64	
65	    /** Dedicated audit logger recording successful owner creations. */
66	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
67	
68	    private final ClinicService clinicService;
69	
70	    private final OwnerMapper ownerMapper;
71	
72	    private final PetMapper petMapper;
73	
74	    private final VisitMapper visitMapper;
75	
76	    public OwnerRestControllerV1(ClinicService clinicService,
77	                                 OwnerMapper ownerMapper,
78	                                 PetMapper petMapper,
79	                                 VisitMapper visitMapper) {
80	        this.clinicService = clinicService;
81	        this.ownerMapper = ownerMapper;
82	        this.petMapper = petMapper;
83	        this.visitMapper = visitMapper;
84	    }
85	
86	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
87	    @Override
88	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
89	        Collection<Owner> owners;
90	        if (lastName != null) {
91	            owners = this.clinicService.findOwnerByLastName(lastName);
92	        } else {
93	            owners = this.clinicService.findAllOwners();
94	        }
95	        if (owners.isEmpty()) {
96	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
97	        }
98	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
99	    }
100	
101	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
102	    @Override
103	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
104	        Owner owner = this.clinicService.findOwnerById(ownerId);
105	        if (owner == null) {
106	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
107	        }
108	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
109	    }
110	
111	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
112	    @Override
113	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
114	        HttpHeaders headers = new HttpHeaders();
115	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
116	        owner.setTelephone(normalizeTelephone(owner.getTelephone()));
117	        owner.setCity(resolveCity(owner.getCity()));
118	        if (isDuplicateOwner(owner) || isDuplicateEmail(owner)) {
119	            return new ResponseEntity<>(HttpStatus.CONFLICT);
120	        }
121	        if (isDailyRegistrationLimitReached()) {
122	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
123	        }
124	        if (isCityCapacityReached(owner.getCity())) {
125	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
126	        }
127	        if (owner.getRegistrationDate() == null) {
128	            owner.setRegistrationDate(LocalDate.now());
129	        }
130	        owner.setMembershipNumber(this.clinicService.findAllOwners().size() + 1);
131	        owner.setMembershipTier(this.clinicService.findAllOwners().size() < 100 ? "FOUNDING" : "STANDARD");
132	        owner.setCustomerCode(nextCustomerCode(owner.getCity()));
133	        owner.setNamesakeCount(countNamesakes(owner.getLastName()));
134	        owner.setSharesHousehold(sharesHousehold(owner));
135	        owner.setLocality(determineLocality(owner.getCity()));
136	        int sharedAreaCodeCount = countOwnersSharingAreaCode(owner.getTelephone());
137	        this.clinicService.saveOwner(owner);
138	        AUDIT.info("Owner created by user={} ownerId={} membershipNumber={}",
139	            currentUsername(), owner.getId(), owner.getMembershipNumber());
140	        if (sharedAreaCodeCount >= 5) {
141	            AUDIT.warn("Possible bulk signup: owner ownerId={} telephone area code {} shared by {} existing owners",
142	                owner.getId(), areaCode(owner.getTelephone()), sharedAreaCodeCount);
143	        }
144	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
145	        headers.setLocation(UriComponentsBuilder.newInstance()
146	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
147	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
148	    }
149	
150	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
151	    @Override
152	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
153	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
154	        if (currentOwner == null) {
155	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
156	        }
157	        currentOwner.setAddress(ownerFieldsDto.getAddress());
158	        currentOwner.setCity(ownerFieldsDto.getCity());
159	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
160	        currentOwner.setLastName(ownerFieldsDto.getLastName());
161	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
162	        this.clinicService.saveOwner(currentOwner);
163	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
164	    }
165	
166	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
167	    @Transactional
168	    @Override
169	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
170	        Owner owner = this.clinicService.findOwnerById(ownerId);
171	        if (owner == null) {
172	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
173	        }
174	        this.clinicService.deleteOwner(owner);
175	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
176	    }
177	
178	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
179	    @Override
180	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
181	        Owner owner = this.clinicService.findOwnerById(ownerId);
182	        if (owner == null) {
183	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
184	        }
185	        HttpHeaders headers = new HttpHeaders();
186	        Pet pet = petMapper.toPet(petFieldsDto);
187	        owner.setId(ownerId);
188	        pet.setOwner(owner);
189	        pet.getType().setName(null);
190	        this.clinicService.savePet(pet);
191	        PetDto petDto = petMapper.toPetDto(pet);
192	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
193	            .buildAndExpand(pet.getId()).toUri());
194	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
195	    }
196	
197	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
198	    @Override
199	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
200	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
201	        if (currentOwner != null) {
202	            Pet currentPet = this.clinicService.findPetById(petId);
203	            if (currentPet != null) {
204	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
205	                currentPet.setName(petFieldsDto.getName());
206	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
207	                this.clinicService.savePet(currentPet);
208	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
209	            }
210	        }
211	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
212	    }
213	
214	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
215	    @Override
216	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
217	        HttpHeaders headers = new HttpHeaders();
218	        Visit visit = visitMapper.toVisit(visitFieldsDto);
219	        Pet pet = new Pet();
220	        pet.setId(petId);
221	        visit.setPet(pet);
222	        this.clinicService.saveVisit(visit);
223	        VisitDto visitDto = visitMapper.toVisitDto(visit);
224	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
225	            .buildAndExpand(visit.getId()).toUri());
226	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
227	    }
228	
229	
230	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
231	    @Override
232	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
233	        Owner owner = this.clinicService.findOwnerById(ownerId);
234	        if (owner != null) {
235	            Pet pet = owner.getPet(petId);
236	            if (pet != null) {
237	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
238	            }
239	        }
240	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
241	    }
242	
243	    /**
244	     * Returns the name of the currently authenticated user, or {@code "anonymous"} if there is
245	     * no authentication in the current security context.
246	     *
247	     * @return the authenticated user name for audit logging
248	     */
249	    private static String currentUsername() {
250	        Authentication authentication = SecurityContextHolder.getContext().getAuthentication();
251	        if (authentication == null || authentication.getName() == null) {
252	            return "anonymous";
253	        }
254	        return authentication.getName();
255	    }
256	
257	    /**
258	     * Resolves the city name to use for a newly created owner. The supplied city is
259	     * title-cased (each whitespace-separated word starts with an upper-case letter and the
260	     * remaining letters are lower-cased), for example {@code "new york"} becomes
261	     * {@code "New York"}. However, if an owner already exists in that city (matched ignoring
262	     * letter case), the existing owner's exact spelling of the city name is reused instead, so
263	     * that all owners in a city share a single canonical spelling.
264	     *
265	     * @param city the city supplied for the owner being created, may be {@code null}
266	     * @return the city name to store and return for the owner
267	     */
268	    private String resolveCity(String city) {
269	        if (city == null) {
270	            return null;
271	        }
272	        String existingCity = this.clinicService.findAllOwners().stream()
273	            .map(Owner::getCity)
274	            .filter(existing -> existing != null && existing.equalsIgnoreCase(city))
275	            .findFirst()
276	            .orElse(null);
277	        if (existingCity != null) {
278	            return existingCity;
279	        }
280	        return toTitleCase(city);
281	    }
282	
283	    /**
284	     * Title-cases the given text so that each whitespace-separated word starts with an
285	     * upper-case letter and the remaining letters are lower-cased, for example
286	     * {@code "new york"} and {@code "NEW YORK"} both become {@code "New York"}. The original
287	     * spacing between words is preserved.
288	     *
289	     * @param value the text to title-case
290	     * @return the title-cased text
291	     */
292	    private static String toTitleCase(String value) {
293	        StringBuilder result = new StringBuilder(value.length());
294	        boolean startOfWord = true;
295	        for (int i = 0; i < value.length(); i++) {
296	            char ch = value.charAt(i);
297	            if (Character.isWhitespace(ch)) {
298	                startOfWord = true;
299	                result.append(ch);
300	            } else if (startOfWord) {
301	                result.append(Character.toUpperCase(ch));
302	                startOfWord = false;
303	            } else {
304	                result.append(Character.toLowerCase(ch));
305	            }
306	        }
307	        return result.toString();
308	    }
309	
310	    /**
311	     * Builds the customer code for a newly created owner, formatted as
312	     * {@code '<UPPERCASE_CITY>-<NNNN>'} where {@code NNNN} is one more than the number of
313	     * owners already registered in that city, zero-padded to four digits (e.g.
314	     * {@code 'LONDON-0007'}). Cities are matched ignoring letter case so the sequence is
315	     * consistent with the upper-cased prefix.
316	     *
317	     * @param city the city of the owner being created
318	     * @return the assigned customer code
319	     */
320	    private String nextCustomerCode(String city) {
321	        long ownersInCity = this.clinicService.findAllOwners().stream()
322	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
323	            .count();
324	        return city.toUpperCase() + "-" + String.format("%04d", ownersInCity + 1);
325	    }
326	
327	    /**
328	     * Counts how many existing owners share the given last name at this moment. The count is taken
329	     * over the owners already registered (excluding the owner currently being created, which has not
330	     * yet been persisted); last names are compared for exact equality.
331	     *
332	     * @param lastName the last name of the owner being created
333	     * @return the number of other owners that currently share the given last name
334	     */
335	    private int countNamesakes(String lastName) {
336	        return (int) this.clinicService.findAllOwners().stream()
337	            .filter(existing -> Objects.equals(existing.getLastName(), lastName))
338	            .count();
339	    }
340	
341	    /**
342	     * Determines whether, at the moment the owner is being created, another owner already shares
343	     * the same household &mdash; that is, an existing owner has both the same address and the same
344	     * city. Address and city are compared for exact equality, using the values resolved for the
345	     * owner being created (which has not yet been persisted).
346	     *
347	     * @param owner the candidate owner to check
348	     * @return {@code true} if an existing owner already has the same address and city
349	     */
350	    private boolean sharesHousehold(Owner owner) {
351	        return this.clinicService.findAllOwners().stream()
352	            .anyMatch(existing -> Objects.equals(existing.getAddress(), owner.getAddress())
353	                && Objects.equals(existing.getCity(), owner.getCity()));
354	    }
355	
356	    /**
357	     * Determines the locality of the owner being created, based on the given city. The city is
358	     * {@code "local"} if it is the single most common city among the existing owners at this moment
359	     * (before the owner being created is persisted); otherwise it is {@code "remote"}. Cities are
360	     * compared ignoring letter case. If there are no existing owners, or if two or more cities are
361	     * tied for the most common, there is no single most common city and the result is
362	     * {@code "remote"}.
363	     *
364	     * @param city the city of the owner being created, may be {@code null}
365	     * @return {@code "local"} or {@code "remote"}
366	     */
367	    private String determineLocality(String city) {
368	        if (city == null) {
369	            return "remote";
370	        }
371	        Map<String, Long> countsByCity = this.clinicService.findAllOwners().stream()
372	            .map(Owner::getCity)
373	            .filter(Objects::nonNull)
374	            .collect(Collectors.groupingBy(existing -> existing.toLowerCase(), Collectors.counting()));
375	        if (countsByCity.isEmpty()) {
376	            return "remote";
377	        }
378	        long max = Collections.max(countsByCity.values());
379	        List<String> mostCommon = countsByCity.entrySet().stream()
380	            .filter(entry -> entry.getValue() == max)
381	            .map(Map.Entry::getKey)
382	            .toList();
383	        if (mostCommon.size() == 1 && mostCommon.get(0).equals(city.toLowerCase())) {
384	            return "local";
385	        }
386	        return "remote";
387	    }
388	
389	    /**
390	     * Determines whether the maximum number of owners that may be registered on a single day has
391	     * already been reached. At most 20 owners may be created per day; the count is taken over the
392	     * owners whose registration date is today.
393	     *
394	     * @return {@code true} if 20 or more owners have already been registered today
395	     */
396	    private boolean isDailyRegistrationLimitReached() {
397	        LocalDate today = LocalDate.now();
398	        long ownersToday = this.clinicService.findAllOwners().stream()
399	            .filter(existing -> today.equals(existing.getRegistrationDate()))
400	            .count();
401	        return ownersToday >= 20;
402	    }
403	
404	    /**
405	     * Determines whether the city of the owner being created has already reached its capacity of
406	     * owners. At most 8 owners may be registered in a single city; the count is taken over the
407	     * existing owners whose city matches (ignoring letter case) the given city.
408	     *
409	     * @param city the city of the owner being created, may be {@code null}
410	     * @return {@code true} if the city already contains 8 or more owners
411	     */
412	    private boolean isCityCapacityReached(String city) {
413	        if (city == null) {
414	            return false;
415	        }
416	        long ownersInCity = this.clinicService.findAllOwners().stream()
417	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
418	            .count();
419	        return ownersInCity >= 8;
420	    }
421	
422	    /**
423	     * Counts how many existing owners share the area code (the first three digits of the
424	     * digits-only telephone number) with the given telephone. The count is taken over the owners
425	     * already registered (excluding the owner currently being created, which has not yet been
426	     * persisted). Owners without an area code &mdash; that is, whose telephone has fewer than three
427	     * digits &mdash; are never counted, and a candidate telephone without an area code matches
428	     * nobody.
429	     *
430	     * @param telephone the digits-only telephone of the owner being created, may be {@code null}
431	     * @return the number of existing owners sharing the same three-digit area code
432	     */
433	    private int countOwnersSharingAreaCode(String telephone) {
434	        String areaCode = areaCode(telephone);
435	        if (areaCode == null) {
436	            return 0;
437	        }
438	        return (int) this.clinicService.findAllOwners().stream()
439	            .map(existing -> areaCode(normalizeTelephone(existing.getTelephone())))
440	            .filter(areaCode::equals)
441	            .count();
442	    }
443	
444	    /**
445	     * Extracts the area code &mdash; the first three digits &mdash; from a digits-only telephone
446	     * number. Returns {@code null} when the telephone is {@code null} or has fewer than three
447	     * digits.
448	     *
449	     * @param telephone the digits-only telephone number, may be {@code null}
450	     * @return the three-digit area code, or {@code null} if unavailable
451	     */
452	    private static String areaCode(String telephone) {
453	        if (telephone == null || telephone.length() < 3) {
454	            return null;
455	        }
456	        return telephone.substring(0, 3);
457	    }
458	
459	    /**
460	     * Determines whether an owner already exists that uses the same telephone number as the
461	     * given candidate. Telephone numbers are compared digits-only, so formatting characters
462	     * such as spaces, dashes and parentheses are ignored.
463	     *
464	     * @param owner the candidate owner to check
465	     * @return {@code true} if an owner with the same telephone number already exists
466	     */
467	    private boolean isDuplicateOwner(Owner owner) {
468	        String telephone = normalizeTelephone(owner.getTelephone());
469	        return this.clinicService.findAllOwners().stream()
470	            .anyMatch(existing -> Objects.equals(normalizeTelephone(existing.getTelephone()), telephone));
471	    }
472	
473	    /**
474	     * Determines whether an owner already exists that uses the same email address as the
475	     * given candidate. Owners without an email address are never considered duplicates.
476	     * The comparison ignores letter case and surrounding or repeated whitespace.
477	     *
478	     * @param owner the candidate owner to check
479	     * @return {@code true} if an owner with the same email address already exists
480	     */
481	    private boolean isDuplicateEmail(Owner owner) {
482	        String email = normalize(owner.getEmail());
483	        if (email == null || email.isEmpty()) {
484	            return false;
485	        }
486	        return this.clinicService.findAllOwners().stream()
487	            .anyMatch(existing -> Objects.equals(normalize(existing.getEmail()), email));
488	    }
489	
490	    /**
491	     * Normalizes a value for duplicate detection so that comparisons ignore letter case and
492	     * surrounding or repeated whitespace. Leading and trailing whitespace is stripped, any run
493	     * of internal whitespace collapses to a single space, and the result is lower-cased. For
494	     * example {@code "  John   Smith "} and {@code "John Smith"} both normalize to
495	     * {@code "john smith"}.
496	     *
497	     * @param value the value to normalize, may be {@code null}
498	     * @return the normalized value, or {@code null} if {@code value} is {@code null}
499	     */
500	    private static String normalize(String value) {
501	        if (value == null) {
502	            return null;
503	        }
504	        return value.strip().replaceAll("\\s+", " ").toLowerCase();
505	    }
506	
507	    /**
508	     * Normalizes a telephone number to digits only by stripping every non-digit character
509	     * (such as spaces, dashes and parentheses). This is used both to store telephone numbers
510	     * in a canonical form and to compare them for uniqueness, so that {@code "(613) 555-0100"}
511	     * and {@code "6135550100"} are treated as the same number.
512	     *
513	     * @param value the telephone number to normalize, may be {@code null}
514	     * @return the digits-only telephone number, or {@code null} if {@code value} is {@code null}
515	     */
516	    private static String normalizeTelephone(String value) {
517	        if (value == null) {
518	            return null;
519	        }
520	        return value.replaceAll("\\D", "");
521	    }
522	}
